const m=(n,t,a)=>n<t?t:n>a?a:n;export function spanFor(n,t){const a=m((n-.5)/.8,0,1);return t.narrowSpan+(t.wideSpan-t.narrowSpan)*a}export function distanceFor(n,t,a){const e=Math.atan(Math.tan(a*Math.PI/360)*t);return n/2/Math.tan(e)}export function cameraFor(n,t,a,e,c=null){let r=spanFor(n,t),o=a,x=e;if(c&&e){const g=Math.min(e.x,c.x)-t.includeMargin,p=Math.max(e.x,c.x)+t.includeMargin;r=m(p-g,r,t.maxSpan),x={x:(g+p)/2,z:e.z},o={minX:a.minX,maxX:Math.max(a.maxX,p)}}const s=distanceFor(r,n,t.fovDegrees),i=Math.hypot(t.height,t.back),u=t.height/i,h=t.back/i,M=Math.max(0,(o.maxX-o.minX)/2-r/2+1),f=(o.minX+o.maxX)/2;let y=t.target.x,z=t.target.z;if(x){y=m(x.x,f-M,f+M);const g=1-m((n-.5)/.8,0,1);z=t.target.z+(e.z-t.target.z)*.5*g}return{position:{x:y,y:t.target.y+u*s,z:z+h*s},target:{x:y,y:t.target.y,z},span:r,distance:s}}export function cameraOn(n,t,a,e){const c=distanceFor(e,t,a.fovDegrees),r=Math.hypot(a.height,a.back);return{position:{x:n.x,y:a.target.y+a.height/r*c,z:n.z+a.back/r*c},target:{x:n.x,y:a.target.y,z:n.z},span:e,distance:c}}export function cameraCast(n,t,a,e,c=2.2){const r=Math.tan(a.fovDegrees*Math.PI/360),o=c/e.height/(2*r),x=1.4/e.width/(2*r*t),s=Math.max(o,x),i=.3,u=Math.hypot(i,1),h={x:n.x,y:.95,z:n.z};return{position:{x:h.x,y:h.y+i/u*s,z:h.z+s/u},target:h,distance:s}}export function castFrame(n,t){if(n>=720){const a=Math.min(380,n-32)+32;return{width:(n-a)/n,height:1,shiftX:a/2,shiftY:0}}return{width:1,height:.44,shiftX:0,shiftY:t*.28}}export function rayToGround(n,t){if(t.y>=-1e-6)return null;const a=-n.y/t.y;return{x:n.x+t.x*a,z:n.z+t.z*a}}export function ease(n,t,a,e){return t+(n-t)*Math.exp(-a*e)}
